"""Items 0(a), 0(b): the group generated by q1, q2, its classes, characters, and V_{l/2} decompositions.

Everything derived here from the two generators:
  - closure by BFS in exact Q(sqrt5) quaternion arithmetic;
  - conjugacy classes by exact conjugation;
  - characters by Burnside's class-algebra method: class multiplication constants a_ijk (exact integers),
    common eigenvectors found numerically (mpmath, 30 and 60 digits), entries identified in Q(sqrt5)
    by PSLQ, then verified EXACTLY (class-algebra eigen-equations, row and column orthogonality);
  - chi_{V_{l/2}}(g) = U_l(Re g) (Chebyshev U, the SU(2) character), cross-checked numerically
    against traces of explicit D^j built in su2.py.
"""
import os, sys, json, random
from fractions import Fraction as F

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import mpmath
import numpy as np
from q5 import Q5, qmul, qconj, qnorm2, ONE, PHI, PHI_INV, q1, q2, H
from checks import check, summary, PLANT
import su2

out = {}

# ---------- 0(a) norms ----------
q2_for_norm = q2 if PLANT != "q2norm" else (PHI * H, PHI * H, Q5(H), Q5(0))
n1, n2 = qnorm2(q1), qnorm2(q2_for_norm)
print("|q1|^2 =", n1, " |q2|^2 =", n2)
check("0(a) |q1| = 1 exactly", n1 == 1)
check("0(a) |q2| = 1 exactly", n2 == 1)

# ---------- closure ----------
G = [ONE]
seen = {ONE}
frontier = [ONE]
while frontier:
    nxt = []
    for g in frontier:
        for s in (q1, q2):
            h = qmul(g, s)
            if h not in seen:
                seen.add(h); G.append(h); nxt.append(h)
    frontier = nxt
    if len(G) > 5000:
        raise SystemExit("group not closing below 5000 elements")
order = len(G)
print("order of Gamma_0 =", order)
idx = {g: i for i, g in enumerate(G)}
# closure check: product table closes and inverses present
closed = all(qmul(a, b) in seen for a in G for b in (q1, q2)) and all(qconj(a) in seen for a in G)
check("0(a) set is closed under generators and inverses", closed)
check("0(a) every element is a unit quaternion", all(qnorm2(g) == 1 for g in G))


def elt_order(g):
    k, p = 1, g
    while p != ONE:
        p = qmul(p, g); k += 1
    return k


# ---------- classes ----------
cls_of = [-1] * order
classes = []
for i, x in enumerate(G):
    if cls_of[i] >= 0:
        continue
    orb = {qmul(qmul(g, x), qconj(g)) for g in G}
    c = len(classes)
    for y in orb:
        cls_of[idx[y]] = c
    classes.append(sorted(idx[y] for y in orb))
# sort classes by (element order, real part)
info = []
for c, mem in enumerate(classes):
    rep = G[mem[0]]
    info.append((elt_order(rep), float(rep[0]), c))
info.sort()
perm = [c for _, _, c in info]
classes = [classes[c] for c in perm]
newlab = {c: k for k, c in enumerate(perm)}
cls_of = [newlab[c] for c in cls_of]
nc = len(classes)
sizes = [len(m) for m in classes]
reps = [G[m[0]] for m in classes]
# real part is a class invariant here; record and check it is constant on each class
re_const = all(all(G[i][0] == reps[k][0] for i in classes[k]) for k in range(nc))
check("0(a) real part constant on each class", re_const)
check("0(a) class sizes sum to group order", sum(sizes) == order)
print("classes (k: element order, Re g, size):")
cls_out = []
for k in range(nc):
    o = elt_order(reps[k])
    print(f"  C{k}: order {o}, Re = {reps[k][0]}, size {sizes[k]}")
    cls_out.append({"label": f"C{k}", "element order": o, "Re g": str(reps[k][0]), "size": sizes[k]})

# ---------- Burnside class algebra ----------
a = [[[0] * nc for _ in range(nc)] for _ in range(nc)]  # a[i][j][k]
for k in range(nc):
    z = reps[k]
    for i in range(nc):
        for xi in classes[i]:
            y = qmul(qconj(G[xi]), z)  # x y = z
            a[i][cls_of[idx[y]]][k] += 1
# sanity: sum_j a_ijk = |C_i|
check("0(a) class constants: sum_j a_ijk = |C_i|", all(sum(a[i][j][k] for j in range(nc)) == sizes[i] for i in range(nc) for k in range(nc)))
id_cls = cls_of[idx[ONE]]


def numeric_table(dps, seed):
    mpmath.mp.dps = dps
    rnd = random.Random(seed)
    r = [rnd.randint(1, 97) for _ in range(nc)]
    A = mpmath.matrix(nc, nc)
    for i in range(nc):
        for j in range(nc):
            for k in range(nc):
                A[j, k] += r[i] * a[i][j][k]
    E, ER = mpmath.eig(A)
    rows = []
    for t in range(nc):
        w = [ER[k, t] / ER[id_cls, t] for k in range(nc)]
        s = mpmath.fsum(abs(w[k]) ** 2 / sizes[k] for k in range(nc))
        dim = mpmath.sqrt(order / s)
        rows.append([dim * w[k] / sizes[k] for k in range(nc)])
    return rows


def identify(x, dps):
    mpmath.mp.dps = dps
    if abs(mpmath.im(x)) > mpmath.mpf(10) ** (-(dps - 8)):
        return None
    x = mpmath.re(x)
    if abs(x) < mpmath.mpf(10) ** (-(dps - 8)):
        return Q5(0)  # zero; confirmed by the exact checks below
    rel = mpmath.pslq([x, 1, mpmath.sqrt(5)], maxcoeff=1000, maxsteps=10 ** 5, tol=mpmath.mpf(10) ** (-(dps - 8)))
    if rel is None or rel[0] == 0:
        return None
    return Q5(F(-rel[1], rel[0]), F(-rel[2], rel[0]))


tables = {}
for dps, seed in ((30, 1), (60, 2)):
    rows = numeric_table(dps, seed)
    ex = [[identify(v, dps) for v in row] for row in rows]
    ok = all(v is not None for row in ex for v in row)
    check(f"0(a) every character value identified in Q(sqrt5) at {dps} digits (denominator <= 1000)", ok)
    ex.sort(key=lambda row: (row[id_cls].a, [float(v) for v in row]))
    tables[dps] = ex
check("0(a) identifications at 30 and 60 digits agree", tables[30] == tables[60])
chars = tables[60]
if PLANT == "char":
    chars[5][6] = chars[5][6].galois() + 1  # planted defect: one wrong entry
nirr = len(chars)
dims = [row[id_cls] for row in chars]

# exact verification
eig_ok = True
for row in chars:
    om = [Q5(sizes[k]) * row[k] / row[id_cls] for k in range(nc)]
    for i in range(nc):
        for j in range(nc):
            if sum((Q5(a[i][j][k]) * om[k] for k in range(nc)), Q5(0)) != om[i] * om[j]:
                eig_ok = False
check("0(a) EXACT: each row satisfies the class-algebra eigen-equations", eig_ok)
row_ok = all(sum((Q5(sizes[k]) * chars[p][k] * chars[q][k] for k in range(nc)), Q5(0)) / order == (1 if p == q else 0)
             for p in range(nirr) for q in range(nirr))
check("0(a) EXACT: row orthonormality (values real)", row_ok)
col_ok = all(sum((chars[p][k] * chars[p][l] for p in range(nirr)), Q5(0)) == (Q5(F(order, sizes[k])) if k == l else 0)
             for k in range(nc) for l in range(nc))
check("0(a) EXACT: column orthogonality", col_ok)
check("0(a) number of irreducibles = number of classes", nirr == nc)
check("0(a) sum of dim^2 = |G|", sum((d * d for d in dims), Q5(0)) == order)


# ---------- 0(b): V_{l/2} restricted ----------
def U_cheb(l, w):
    u0, u1 = Q5(1), Q5(2) * w
    if l == 0:
        return u0
    for _ in range(l - 1):
        u0, u1 = u1, Q5(2) * w * u1 - u0
    return u1


LMAX_B = 20
LMAX_E = 60  # for Block E's "next level"
mult = {}
mult_ok = True
for l in range(LMAX_E + 1):
    chi_l = [U_cheb(l, reps[k][0]) for k in range(nc)]
    if PLANT == "mult" and l == 3:
        chi_l[5] = chi_l[5] + 1
    for p in range(nirr):
        m = sum((Q5(sizes[k]) * chi_l[k] * chars[p][k] for k in range(nc)), Q5(0)) / order
        if not (m.is_rational_integer() and m.a >= 0):
            mult_ok = False
        mult[(p, l)] = m
check(f"0(b) EXACT: all multiplicities for l <= {LMAX_E} are non-negative integers", mult_ok)
dimsum_ok = all(sum((mult[(p, l)] * dims[p] for p in range(nirr)), Q5(0)) == l + 1 for l in range(LMAX_E + 1))
check("0(b) EXACT: sum_rho mult*dim = l+1 for every l", dimsum_ok)

# numeric cross-check of U_l(Re g) = tr D^{l/2}(g), and of the matrix convention
mpmath.mp.dps = 30
hom_ok = all(np.allclose(su2.qmat(qmul(x, y)), su2.qmat(x) @ su2.qmat(y)) for x in G[:40] for y in (q1, q2))
check("conv: quaternion->SU(2) map is a homomorphism (sampled)", hom_ok)
tr_err = 0.0
dhom_err = 0.0
for l in range(LMAX_B + 1):
    lp = l + 1 if PLANT == "trace" else l
    for k in range(nc):
        tr = np.trace(su2.D(l, su2.qmat(reps[k])))
        tr_err = max(tr_err, abs(tr - float(U_cheb(lp, reps[k][0]))))
    Ux, Uy = su2.qmat(q1), su2.qmat(q2)
    dhom_err = max(dhom_err, np.abs(su2.D(l, Ux @ Uy) - su2.D(l, Ux) @ su2.D(l, Uy)).max())
check("0(b) tr D^{l/2}(g) = U_l(Re g) numerically, l <= 20, all classes", tr_err < 1e-9, f"max err {tr_err:.2e}")
check("conv: D^j is a homomorphism, l <= 20", dhom_err < 1e-9, f"max err {dhom_err:.2e}")

# ---------- labels and report ----------
levels = {p: [l for l in range(LMAX_E + 1) if mult[(p, l)].a > 0] for p in range(nirr)}
labels = []
for p in range(nirr):
    d = int(dims[p].a)
    labels.append(f"dim{d}_n{levels[p][0]}")
print()
print("character table (rows: irreps labelled dim<d>_n<lowest level>; columns C0..C8):")
for p in range(nirr):
    print(f"  {labels[p]:>10}: " + " | ".join(str(v) for v in chars[p]))
print()
print("0(b) levels l <= 20 with multiplicity (l: mult):")
b_out = {}
for p in range(nirr):
    lv = {str(l): int(mult[(p, l)].a) for l in range(LMAX_B + 1) if mult[(p, l)].a > 0}
    b_out[labels[p]] = {"dim": int(dims[p].a), "levels": lv}
    print(f"  {labels[p]:>10}: " + ", ".join(f"{l}:{m}" for l, m in lv.items()))

names = {"R2": (2, 7), "R4": (3, 6), "R5": (4, 6)}
if PLANT == "names":
    names["R5"] = (5, 6)  # planted: a name that matches no irreducible
name_map = {}
for nm, (d, n) in names.items():
    hits = [labels[p] for p in range(nirr) if int(dims[p].a) == d and levels[p][0] == n]
    check(f"0(b) name {nm} (dim {d}, lowest level {n}) picks out exactly one irreducible", len(hits) == 1, f"hits {hits}")
    name_map[nm] = hits
    print(f"  {nm} -> {hits}")
# multiplicity one at the lowest level for the named slots (0(c) premise, checked here only as a remark)
for nm, (d, n) in names.items():
    for p in range(nirr):
        if int(dims[p].a) == d and levels[p][0] == n:
            print(f"  {nm}: multiplicity at level {n} = {mult[(p, n)]}")

out["0(a)"] = {
    "norm q1": "1" if n1 == 1 else str(n1), "norm q2": "1" if n2 == 1 else str(n2),
    "order": order,
    "classes": cls_out,
    "characters": {labels[p]: [str(v) for v in chars[p]] for p in range(nirr)},
}
out["0(b)"] = b_out
out["0(b)"]["names"] = {k: v[0] if len(v) == 1 else v for k, v in name_map.items()}
# full table to l = 60 for Block E
out["_mult_to_60"] = {labels[p]: {str(l): int(mult[(p, l)].a) for l in range(LMAX_E + 1) if mult[(p, l)].a > 0} for p in range(nirr)}
out["_dims"] = {labels[p]: int(dims[p].a) for p in range(nirr)}
if PLANT is None:
    os.makedirs(os.path.join(HERE, "out"), exist_ok=True)
    with open(os.path.join(HERE, "out", "s01.json"), "w") as f:
        json.dump(out, f, indent=1)
summary()
